<script setup lang="ts">
import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{useRouter}from'vue-router';import{api,type ApiResponse,type Product}from'@whaashop/shared';
interface Category{id:number;name:string;sortOrder:number;children:Category[]}interface Banner{id:number;title:string;subtitle:string;imageUrl:string;targetUrl?:string;buttonText:string}
const router=useRouter(),products=ref<Product[]>([]),hot=ref<Product[]>([]),newest=ref<Product[]>([]),categories=ref<Category[]>([]),banners=ref<Banner[]>([]),current=ref(0),loading=ref(true),selectedCategory=ref<number>();const icons=['⌚','⌨','👕','🥜','🏠','🎧'];let timer:number|undefined;
const active=computed(()=>banners.value[current.value]);const selectedName=computed(()=>categories.value.flatMap(v=>[v,...v.children]).find(v=>v.id===selectedCategory.value)?.name);
onMounted(async()=>{try{const[p,h,n,c,b]=await Promise.all([api.get<ApiResponse<Product[]>>('/shop/products/weekly-picks'),api.get<ApiResponse<Product[]>>('/shop/products/hot-picks'),api.get<ApiResponse<Product[]>>('/shop/products/new-arrivals'),api.get<ApiResponse<Category[]>>('/shop/categories/tree'),api.get<ApiResponse<Banner[]>>('/shop/home-banners')]);products.value=p.data.data;hot.value=h.data.data;newest.value=n.data.data;categories.value=c.data.data;banners.value=b.data.data;start()}finally{loading.value=false}});onBeforeUnmount(()=>clearInterval(timer));
function start(){clearInterval(timer);if(banners.value.length>1)timer=window.setInterval(()=>next(),5000)}function next(){if(banners.value.length)current.value=(current.value+1)%banners.value.length}function prev(){if(banners.value.length)current.value=(current.value-1+banners.value.length)%banners.value.length}function select(i:number){current.value=i;start()}function go(){const url=active.value?.targetUrl;if(!url)return document.querySelector('#featured')?.scrollIntoView({behavior:'smooth'});if(url.startsWith('/'))router.push(url);else window.open(url,'_blank','noopener')}async function filterCategory(id?:number){selectedCategory.value=id;loading.value=true;try{products.value=(await api.get<ApiResponse<Product[]>>('/shop/products/weekly-picks',{params:{categoryId:id}})).data.data;document.querySelector('#featured')?.scrollIntoView({behavior:'smooth'})}finally{loading.value=false}}
</script>
<template><div class="home"><div class="container"><section v-if="active" class="hero product-carousel"><article v-for="(b,i) in banners" :key="b.id" :class="['carousel-slide',{active:i===current}]"><img :src="b.imageUrl" :alt="b.title"><div class="carousel-shade"></div><div class="carousel-copy"><span class="hero-pill">WhaaShop 商品精选</span><h1>{{b.title}}</h1><p>{{b.subtitle}}</p><button class="btn light" @click="go">{{b.buttonText||'立即选购'}} →</button></div></article><button v-if="banners.length>1" class="carousel-arrow left" @click="prev">‹</button><button v-if="banners.length>1" class="carousel-arrow right" @click="next">›</button><div class="carousel-dots"><button v-for="(b,i) in banners" :key="b.id" :class="{active:i===current}" :aria-label="`查看${b.title}`" @click="select(i)"></button></div><div class="carousel-count"><b>0{{current+1}}</b><span>/ 0{{banners.length}}</span></div></section><section v-else class="hero home-hero"><div><span class="hero-pill">WhaaShop 精选商城</span><h1>精选商品持续上新</h1><p>可在管理后台“首页轮播”中配置这里展示的商品、图片和文案。</p></div></section><section class="service-strip"><div><b>✓ 正品保障</b><span>严选品质商品</span></div><div><b>⚡ 极速响应</b><span>本地智能客服</span></div><div><b>▣ 安全支付</b><span>支付宝沙箱保障</span></div><div><b>♡ 用心服务</b><span>真实评价与追评</span></div></section><section id="categories" class="home-section"><div class="section-title"><div><span>SHOP BY CATEGORY</span><h2>分类好物</h2></div><button class="category-all" :class="{active:selectedCategory===undefined}" @click="filterCategory()">全部商品</button></div><div class="category-families"><article v-for="(c,i) in categories" :key="c.id" class="category-family"><button class="category-parent" :class="{active:selectedCategory===c.id}" @click="filterCategory(c.id)"><i>{{icons[i%icons.length]}}</i><span><b>{{c.name}}</b><small>{{c.children.length?`${c.children.length} 个子分类`:'浏览分类商品'}}</small></span><em>→</em></button><div v-if="c.children.length" class="child-categories"><button v-for="child in c.children" :key="child.id" :class="{active:selectedCategory===child.id}" @click="filterCategory(child.id)">{{child.name}}</button></div></article></div></section><section id="featured" class="home-section soft-section"><div class="section-title"><div><span>EDITOR'S PICKS</span><h2>{{selectedName||'本周精选'}}</h2></div><button v-if="selectedCategory!==undefined" class="category-all" @click="filterCategory()">清除筛选 ×</button></div><div v-if="!loading" class="grid product-grid"><router-link v-for="p in products.slice(0,8)" :key="p.id" :to="`/products/${p.id}`" class="product"><div class="product-image"><img :src="p.mainImage" :alt="p.name"><span>精选</span></div><div class="product-body"><h3>{{p.name}}</h3><p class="muted">{{p.subtitle}}</p><div class="product-meta"><span class="price">¥{{p.minPrice}}</span><small>已售 {{p.sales}}</small></div></div></router-link></div><div v-if="!loading&&!products.length" class="panel">该分类暂无上架商品，去看看其他分类吧。</div></section><section class="home-section two-columns"><div><div class="section-title"><div><span>BEST SELLERS</span><h2>热销榜单</h2></div></div><router-link v-for="(p,i) in hot" :key="p.id" :to="`/products/${p.id}`" class="rank-item"><strong>0{{i+1}}</strong><img :src="p.mainImage"><div><b>{{p.name}}</b><span>已售 {{p.sales}} 件</span></div><em>¥{{p.minPrice}}</em></router-link></div><div class="new-box"><span>NEW ARRIVALS</span><h2>新鲜上架</h2><p>探索刚刚抵达的生活灵感</p><div class="mini-products"><router-link v-for="p in newest" :key="p.id" :to="`/products/${p.id}`"><img :src="p.mainImage"><b>{{p.name}}</b></router-link></div></div></section></div></div></template>
<style scoped>.product-carousel{height:500px;padding:0;position:relative;overflow:hidden;background:#7c2d12}.carousel-slide{position:absolute;inset:0;opacity:0;transform:scale(1.03);transition:opacity .65s,transform 1s;pointer-events:none}.carousel-slide.active{opacity:1;transform:scale(1);pointer-events:auto}.carousel-slide>img{width:100%;height:100%;object-fit:cover}.carousel-shade{position:absolute;inset:0;background:linear-gradient(90deg,#431407e8 0%,#7c2d1299 43%,#43140715 78%)}.carousel-copy{position:absolute;left:7%;top:50%;transform:translateY(-50%);width:min(560px,70%);color:#fff}.carousel-copy h1{font-size:52px;line-height:1.12;margin:15px 0;text-shadow:0 4px 18px #0003}.carousel-copy p{font-size:17px;line-height:1.75;color:#ffedd5}.carousel-arrow{position:absolute;top:50%;width:44px;height:44px;border:1px solid #ffffff88;border-radius:50%;background:#ffffff20;color:#fff;font-size:30px;cursor:pointer;backdrop-filter:blur(5px)}.carousel-arrow.left{left:20px}.carousel-arrow.right{right:20px}.carousel-dots{position:absolute;left:7%;bottom:30px;display:flex;gap:8px}.carousel-dots button{width:8px;height:8px;padding:0;border:0;border-radius:99px;background:#ffffff88;transition:.2s;cursor:pointer}.carousel-dots button.active{width:30px;background:#fff}.carousel-count{position:absolute;right:6%;bottom:27px;color:#fff}.carousel-count b{font-size:20px}.carousel-count span{color:#ffffffaa}@media(max-width:700px){.product-carousel{height:420px}.carousel-copy{width:78%;left:9%}.carousel-copy h1{font-size:35px}.carousel-copy p{font-size:14px}.carousel-arrow{display:none}.carousel-count{display:none}}</style>
